class AcceptanceAgent(Agent):
    def step(self, obs):
        neighbours = obs.neighbours
        total = Vec2(0.0, 0.0)
        for n in neighbours:
            distance = norm(n.relative_position)
            if distance > 0.0 and not False:
                total += n.relative_position
        longitudinal = dot(total, obs.heading)
        lateral = dot(total, perpendicular(obs.heading))
        if longitudinal > 0.0:
            speed = min(max(sin(longitudinal) ** 2.0, 0.0), 1.0)
        elif longitudinal == 0.0:
            speed = 0.5
        else:
            speed = abs(cos(longitudinal))
        turning = atan2(lateral, abs(longitudinal) + 1.0)
        return Motion(speed, turning)

class ActiveElasticAgent(Agent):
    def step(self, obs):
        proximal = Vec2(0.0, 0.0)
        sigma_lj = DESIRED_DISTANCE / pow(2.0, 1.0 / POTENTIAL_ALPHA)
        for neighbour in obs.neighbours:
            displacement = neighbour.relative_position
            distance = norm(displacement)
            ratio = sigma_lj / distance
            magnitude = -(4.0 * POTENTIAL_ALPHA * POTENTIAL_EPSILON / distance) * (2.0 * pow(ratio, 2.0 * POTENTIAL_ALPHA) - pow(ratio, POTENTIAL_ALPHA))
            proximal += magnitude * displacement / distance
        forward = K1 * dot(proximal, obs.heading) + U
        turning = K2 * dot(proximal, perpendicular(obs.heading))
        return Motion(forward, turning)

