class MathAgent(Agent):
    def step(self, obs):
        p = 2.0 ** 3.0 ** 2.0
        n = -2.0 ** 2.0
        a = abs(-2.0) + sqrt(4.0) + exp(0.0) + log(1.0)
        b = sin(0.0) + cos(0.0) + tan(0.0)
        c = asin(0.0) + acos(1.0) + atan(0.0) + atan2(0.0, 1.0)
        d = floor(1.9) + ceil(1.1) + min(3.0, 4.0) + max(3.0, 4.0)
        return Motion(p + n + a + b + c + d, 0.0)

