    def step(self, obs):
        if rng.bernoulli(0.35) and not self.role > 2.0:
            turn = rng.normal(0.0, 0.2)
        elif self.role >= 1.0 or False:
            turn = rng.uniform(-0.5, 0.5)
        else:
            turn = -0.1 * 2.0 ** 0.5
